import { useEffect, useState } from 'react';

const seed = [
        { ref: 1042, title: 'VPN drops every 10 minutes', priority: 'Critical', remaining: -30, window: 240, owner: 'Alex Rivera' },
        { ref: 1043, title: 'Printer on floor 2 shows paper jam', priority: 'High', remaining: 75, window: 480, owner: 'Unassigned' },
        { ref: 1044, title: 'New starter laptop setup', priority: 'Medium', remaining: 240, window: 1440, owner: 'Sam Okafor' },
        { ref: 1048, title: 'Disk at 96% on file server', priority: 'Critical', remaining: 80, window: 240, owner: 'Alex Rivera' }
];
type RequestRow = typeof seed[number];
const priority = ['Critical', 'High', 'Medium', 'Low'];
function urgency(row: RequestRow) {
  return row.remaining < 0 ? 0 : row.remaining < 120 ? 1 : 2;
}

export default function SlaPriorityQueue() {
  const [rows, setRows] = useState(seed);
  const [query, setQuery] = useState('');
  const [search, setSearch] = useState('');
  const [selected, setSelected] = useState<number[]>([]);
  const [notice, setNotice] = useState('');
  useEffect(() => {
    const timeout = window.setTimeout(() => setSearch(query.trim().toLowerCase()), 300);
    return () => window.clearTimeout(timeout);
  }, [query]);
  const visible = rows.filter(row => [row.ref, row.title, row.owner, row.priority].join(' ').toLowerCase().includes(search))
    .sort((a, b) => urgency(a) - urgency(b) || a.remaining - b.remaining ||
      priority.indexOf(a.priority) - priority.indexOf(b.priority) || a.ref - b.ref);
  function assign() {
    setRows(previous => previous.map(row => selected.includes(row.ref) ? { ...row, owner: 'Alex Rivera' } : row));
    setNotice('Assigned ' + selected.length + ' request' + (selected.length === 1 ? '' : 's') + ' to Alex Rivera.');
    setSelected([]);
  }
  return <section aria-label="Priority queue" className="grid gap-3 p-3 text-start text-sm">
    <label className="grid gap-1">Search requests
      <input type="search" className="min-w-0 rounded-sm border border-strong bg-surface p-2 text-ink" value={query} onChange={event => { setQuery(event.target.value); setSelected([]); }}/>
    </label>
    <ul className="grid list-none gap-1 p-0">{visible.map(row => <li className="flex flex-wrap items-start gap-2 border-b border-hairline py-2" key={row.ref}>
      <input type="checkbox" aria-label={'Select request ' + row.ref} checked={selected.includes(row.ref)}
        onChange={() => setSelected(ids => ids.includes(row.ref) ? ids.filter(id => id !== row.ref) : [...ids, row.ref])}/>
      <div className="min-w-0 flex-1"><strong>#{row.ref} · {row.title}</strong>
        <span className="block text-xs text-ink-secondary">{row.priority} · {row.owner}</span>
        <span className="font-mono tabular-nums">{Math.abs(row.remaining)}m {row.remaining < 0 ? 'overdue' : 'left'}</span>
        <div className="h-1 w-full bg-subtle"><i className="block h-full bg-accent" style={{width: Math.max(2, Math.min(100, 100 * row.remaining / row.window)) + '%'}}/></div>
      </div></li>)}</ul>
    {!visible.length && <p>No matching requests.</p>}
    {selected.length > 0 && <div className="flex flex-wrap items-center gap-2 border-s-2 border-accent bg-accent-tint p-2 motion-safe:transition motion-safe:starting:translate-y-2 motion-safe:starting:opacity-0"><span>{selected.length} selected</span><button type="button" className="rounded-sm border border-strong bg-surface px-3 py-2 text-ink hover:bg-subtle" onClick={assign}>Assign to me</button></div>}
    <p role="status" className="min-h-5 text-xs text-accent">{notice}</p>
  </section>;
}
